package com.komainos.mantenimiento.service;
import com.komainos.inventario.service.*;import com.komainos.inventario.repository.*;import com.komainos.ejecucion.service.PuertoAnsible;import com.komainos.ejecucion.model.SolicitudEjecucion;import com.komainos.shared.exception.ReglaNegocioException;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor
public class ServicioConectividad {
 private final ServicioServidor servidores;private final GrupoMantenimientoRepositorio grupos;private final ConfiguracionGrupoRepositorio configsGrupo;private final ServicioParametrosSistema parametros;private final ConfiguracionServidorRepositorio configuraciones;private final PuertoCuentasServicio cuentas;private final PuertoAnsible ansible;
 @Transactional(readOnly=true)public ResultadoConexion probar(Integer id){var s=servidores.obtenerSinAlcance(id);Integer cuenta=configuraciones.findByServidorId(id).map(c->c.getIdCuentaServicio()).orElse(null);if(cuenta==null)cuenta=parametros.obtener().getIdCuentaServicioPredeterminada();if(cuenta==null)throw new ReglaNegocioException("Defina una cuenta de servicio para comprobar el acceso");cuentas.exigirAsignable(cuenta,s.familia());var r=ansible.probarConexion(new SolicitudEjecucion(id,s.getHostname(),s.getDireccionIp(),s.familia(),cuenta,"",Map.of(),false,false,1));return new ResultadoConexion(r.simulado(),r.correcto(),r.correcto()?r.salida():r.error());}
 @Transactional(readOnly=true)public List<ConexionServidor> probarGrupo(Integer id){var g=grupos.findConIntegrantesById(id).orElseThrow();Integer cuenta=configsGrupo.findByGrupoId(id).map(c->c.getIdCuentaServicio()).orElse(null);if(cuenta==null)cuenta=parametros.obtener().getIdCuentaServicioPredeterminada();if(cuenta==null)throw new ReglaNegocioException("Defina una cuenta para el grupo");List<ConexionServidor> resultados=new ArrayList<>();for(var s:g.servidores()){cuentas.exigirAsignable(cuenta,s.familia());var r=ansible.probarConexion(new SolicitudEjecucion(s.getId(),s.getHostname(),s.getDireccionIp(),s.familia(),cuenta,"",Map.of(),false,false,1));resultados.add(new ConexionServidor(s.getId(),s.getHostname(),r.simulado(),r.correcto(),r.correcto()?r.salida():r.error()));}return resultados;}
 public record ConexionServidor(Integer idServidor,String servidor,boolean simulado,boolean correcto,String mensaje){}
 public record ResultadoConexion(boolean simulado,boolean correcto,String mensaje){}
}